/** 
 * Send instant message.
 * @param to contact to send message to
 * @param message message to send
 * @throws IllegalStateException in case of bad internal state
 * @throws IllegalArgumentException in case invalid arguments have beenpassed
 */
@Override public void sendInstantMessage(final Contact to,final Message message) throws IllegalStateException, IllegalArgumentException {
  if (message instanceof MessageIrcImpl && ((MessageIrcImpl)message).isCommand()) {
    try {
this      .provider.getIrcStack().command(to,(MessageIrcImpl)message);
    } catch (IndexOutOfBoundsException e) {
      throw new IllegalArgumentException("Invalid message format: " + e.getMessage());
    }
  }
 else {
    this.provider.getIrcStack().message(to,message);
  }
}
```

